message.content:
{
  "diagnosis": "The current implementation of `is_complete` returns `bool(completed)` which is always `True` if `completed` is non-empty. This fails the test case where `required` is `{'a', 'b'}` and `completed` is `{'a'}` because it incorrectly returns `True` instead of `False`.",
  "expected_effect": "The function should check if `completed` is a superset of `required` (i.e., all required items are present in completed).",
  "schema_version": "exp002-diagnosis-update/v1",
  "updates": {
    "harness.py": "def is_complete(required, completed) -> bool:\n    \"\"\"Return whether every required item is complete.\"\"\"\n    return required.issubset(completed)"
  }
}

